  (function(){
    "use strict";

    const API_BASE = "https://api.waktusolat.app"; // domain utama 3
    const root = document.getElementById("ilm-imsakiah");
    const defaultState = (root?.getAttribute("data-default-state") || "").trim();

    const elState = document.getElementById("ilmState");
    const elZone  = document.getElementById("ilmZone");
    const elYear  = document.getElementById("ilmYear");
    const elLoad  = document.getElementById("ilmLoad");
    const elDetect= document.getElementById("ilmDetect");
    const elCSV   = document.getElementById("ilmCSV");
    const elStatus= document.getElementById("ilmStatus");
    const elWrap  = document.getElementById("ilmTableWrap");
    const elTbody = document.querySelector("#ilmTable tbody");

    let ZONES = [];
    let LAST_ROWS = [];

    const pad2 = n => String(n).padStart(2,"0");
    const setStatus = (m,e=false)=>{elStatus.textContent=m||"";elStatus.style.color=e?"#b00020":"#0c3808";};

    const epochToHHMM = (s)=>{const d=new Date(s*1000);return pad2(d.getHours())+":"+pad2(d.getMinutes());};
    const hhmmMinus = (s,minus)=>{const d=new Date((s-minus)*1000);return pad2(d.getHours())+":"+pad2(d.getMinutes());};
    const ymdDisp = (y,m,d)=>{const dt=new Date(y,m-1,d);return pad2(dt.getDate())+"-"+pad2(dt.getMonth()+1)+"-"+dt.getFullYear();};
    const hijriMonth = (h)=>{if(!h||typeof h!=="string")return null;const p=h.split("-");return p[1]?parseInt(p[1],10):null;};

    async function fetchJSON(url){
      const r = await fetch(url,{cache:"no-store"});
      if(!r.ok) throw new Error("HTTP "+r.status);
      return r.json();
    }

    function groupByState(zones){
      const map=new Map();
      zones.forEach(z=>{
        const negeri=z.negeri||"Lain-lain";
        if(!map.has(negeri)) map.set(negeri,[]);
        map.get(negeri).push(z);
      });
      return Array.from(map.entries())
        .sort((a,b)=>a[0].localeCompare(b[0],"ms"))
        .map(([k,v])=>({negeri:k,zones:v.sort((x,y)=>(x.daerah||"").localeCompare(y.daerah||"","ms"))}));
    }

    function populateZones(negeri){
      const zones = ZONES.filter(z=>z.negeri===negeri);
      elZone.innerHTML = zones.map(z=>{
        const label = (z.jakimCode||"") + " — " + (z.daerah||"");
        return `<option value="${z.jakimCode}" target="_blank" rel="internal noopener">${label}</option>`;
      }).join("");
    }

    async function initZones(){
      setStatus("Loading zon…");
      // endpoint zones 4
      ZONES = await fetchJSON(API_BASE + "/zones");
      const grouped = groupByState(ZONES);

      elState.innerHTML = grouped.map(g=>`<option value="${encodeURIComponent(g.negeri)}" target="_blank" rel="internal noopener">${g.negeri}</option>`).join("");
      elYear.value = new Date().getFullYear();

      // auto preselect negeri jika diset di data-default-state
      if(defaultState){
        const idx = Array.from(elState.options).findIndex(o=>decodeURIComponent(o.value)===defaultState);
        if(idx>=0) elState.selectedIndex = idx;
      }

      populateZones(decodeURIComponent(elState.value));
      setStatus("Siap. Pilih zon & klik “Papar Jadual Ramadan”.");
    }

    elState.addEventListener("change", ()=>populateZones(decodeURIComponent(elState.value)));

    async function loadRamadanTable(){
      const negeri = decodeURIComponent(elState.value);
      const zone = elZone.value;
      const year = parseInt(elYear.value,10) || new Date().getFullYear();

      elCSV.disabled=true; LAST_ROWS=[]; elWrap.style.display="none"; elTbody.innerHTML="";
      if(!zone){setStatus("Sila pilih zon.",true);return;}

      const cacheKey="ilm_ramadan_"+zone+"_"+year;
      const cached=localStorage.getItem(cacheKey);
      if(cached){
        try{ const rows=JSON.parse(cached); renderRows(rows); setStatus(`Papar dari cache: ${negeri} (${zone}) — ${year}.`); elCSV.disabled=false; return; }catch(e){}
      }

      setStatus(`Ambil data Ramadan… ${negeri} (${zone}) tahun ${year}.`);

      // v2 solat by zone, month, year 5
      const all=[];
      for(let m=1;m<=12;m++){
        const url = `${API_BASE}/v2/solat/${encodeURIComponent(zone)}?year=${year}&month=${m}`;
        try{
          const data = await fetchJSON(url);
          const prayers = data?.prayers || [];
          prayers.forEach(p=>{
            if(hijriMonth(p.hijri)===9){
              all.push({gYear:year,gMonth:m,gDay:p.day,hijri:p.hijri,fajr:p.fajr,maghrib:p.maghrib});
            }
          });
        }catch(e){}
      }

      if(!all.length){setStatus("Tak jumpa Ramadan untuk tahun ini (API belum ada / data tak lengkap). Cuba tahun semasa.",true);return;}
      all.sort((a,b)=>(a.gMonth-b.gMonth)||(a.gDay-b.gDay));

      const rows = all.map((x,i)=>({
        no:i+1,
        dateMs: ymdDisp(x.gYear,x.gMonth,x.gDay),
        hijri: x.hijri,
        imsak: hhmmMinus(x.fajr, 600),
        subuh: epochToHHMM(x.fajr),
        berbuka: epochToHHMM(x.maghrib)
      }));

      localStorage.setItem(cacheKey, JSON.stringify(rows));
      renderRows(rows);
      setStatus(`Siap: ${negeri} (${zone}) — ${rows.length} hari Ramadan untuk ${year}.`);
      elCSV.disabled=false;
    }

    function renderRows(rows){
      LAST_ROWS=rows;
      elTbody.innerHTML = rows.map(r=>`
        <tr>
          <td>${r.no}</td><td>${r.dateMs}</td><td>${r.hijri}</td>
          <td><b>${r.imsak}</b></td><td>${r.subuh}</td><td><b>${r.berbuka}</b></td>
        </tr>`).join("");
      elWrap.style.display="";
    }

    function downloadCSV(){
      if(!LAST_ROWS.length) return;
      const header=["Hari","TarikhMasihi","TarikhHijri","Imsak","Subuh","BerbukaMaghrib"];
      const lines=[header.join(",")].concat(
        LAST_ROWS.map(r=>[r.no,r.dateMs,r.hijri,r.imsak,r.subuh,r.berbuka].map(v=>`"${String(v).replace(/"/g,'""')}"`).join(","))
      );
      const blob=new Blob([lines.join("\n")],{type:"text/csv;charset=utf-8"});
      const a=document.createElement("a");
      a.href=URL.createObjectURL(blob);
      a.download="jadual-imsak-berbuka-ramadan.csv";
      document.body.appendChild(a); a.click();
      setTimeout(()=>{URL.revokeObjectURL(a.href); a.remove();},0);
    }

    async function detectZoneGPS(){
      if(!navigator.geolocation){setStatus("Browser tak sokong GPS.",true);return;}
      setStatus("Minta lokasi (GPS)…");
      navigator.geolocation.getCurrentPosition(async(pos)=>{
        try{
          const lat=pos.coords.latitude, lon=pos.coords.longitude;
          const z=await fetchJSON(`${API_BASE}/zones/gps?lat=${lat}&long=${lon}`); // 6
          const zone=(z?.zone||"").toUpperCase();
          const match=ZONES.find(x=>(x.jakimCode||"").toUpperCase()===zone);
          if(match){
            const sIdx=Array.from(elState.options).findIndex(o=>decodeURIComponent(o.value)===match.negeri);
            if(sIdx>=0) elState.selectedIndex=sIdx;
            populateZones(match.negeri);
            const zIdx=Array.from(elZone.options).findIndex(o=>o.value.toUpperCase()===zone);
            if(zIdx>=0) elZone.selectedIndex=zIdx;
            setStatus(`Auto-detect: ${match.negeri} — ${match.daerah} (${zone}).`);
          }else setStatus(`Zon GPS ditemui (${zone}) tapi tak match senarai.`,true);
        }catch(e){setStatus("Gagal auto-detect. Sila pilih manual.",true);}
      },()=>setStatus("Lokasi ditolak/gagal. Sila pilih manual.",true),
      {enableHighAccuracy:false,timeout:9000,maximumAge:600000});
    }

    elLoad.addEventListener("click", loadRamadanTable);
    elCSV.addEventListener("click", downloadCSV);
    elDetect.addEventListener("click", detectZoneGPS);

    initZones().catch(()=>setStatus("Gagal load zon (API down/blocked). Cuba refresh.",true));
  })();
